func getAuthRecord(e *core.RequestEvent) (*models.Record, error) {
	// Try to get the auth record from the request context (set by apis.RequireAuth)
	rec := e.Auth
	if rec == nil {
		return nil, errors.New("no auth record in context")
	}
	return rec, nil
}

func handlePresign(app core.App, s3Client *s3.Client) func(e *core.RequestEvent) error {
	presign := newPresignClient(s3Client)
	cfg := loadS3Config()

	return func(e *core.RequestEvent) error {
		rec, err := getAuthRecord(e)
		if err != nil {
			return apis.NewUnauthorizedError("unauthorized", nil)
		}

		key := uuid.New().String()
		expiresAt := time.Now().Add(presignExpires).UTC()

		pendingCol, err := app.Dao().FindCollectionByNameOrId("pending_upload")
		if err != nil {
			return apis.NewApiError(500, "pending_upload collection missing", err)
		}

		row := models.NewRecord(pendingCol)
		row.Set("user", rec.Id)
		row.Set("key", key)
		row.Set("expires_at", expiresAt)
		if err := app.Dao().SaveRecord(row); err != nil {
			return apis.NewApiError(500, "failed to save pending upload", err)
		}

		req, err := presign.PresignPutObject(context.Background(), &s3.PutObjectInput{
			Bucket: aws.String(cfg.Bucket),
			Key:    aws.String(key),
		}, s3.WithPresignExpires(presignExpires))
		if err != nil {
			return apis.NewApiError(500, "failed to presign", err)
		}

		return e.JSON(200, map[string]any{
			"url":       req.URL,
			"key":       key,
			"expiresAt": expiresAt.Format(time.RFC3339),
		})
	}
}

type finalizeRequest struct {
	Key string `json:"key"`
}

func handleFinalize(app core.App, s3Client *s3.Client) func(e *core.RequestEvent) error {
	cfg := loadS3Config()

	return func(e *core.RequestEvent) error {
		rec, err := getAuthRecord(e)
		if err != nil {
			return apis.NewUnauthorizedError("unauthorized", nil)
		}

		var body finalizeRequest
		if err := e.BindBody(&body); err != nil {
			return apis.NewBadRequestError("invalid body", err)
		}
		key := strings.TrimSpace(body.Key)
		if key == "" {
			return apis.NewBadRequestError("missing key", nil)
		}

		pendingCol, err := app.Dao().FindCollectionByNameOrId("pending_upload")
		if err != nil {
			return apis.NewApiError(500, "pending_upload collection missing", err)
		}

		pending, err := app.Dao().FindFirstRecordByFilter(pendingCol, "[[key]] = {:key}", map[string]any{"key": key})
		if err != nil {
			return apis.NewNotFoundError("pending upload not found", err)
		}
		userVal := pending.Get("user")
		userId, _ := userVal.(string)
		if userId == "" {
			return apis.NewNotFoundError("pending upload not found", nil)
		}
		if userId != rec.Id {
			return apis.NewNotFoundError("pending upload not found", nil)
		}

		// HEAD request to verify object exists
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_, headErr := s3Client.HeadObject(ctx, &s3.HeadObjectInput{
			Bucket: aws.String(cfg.Bucket),
			Key:    aws.String(key),
		})
		if headErr != nil {
			var apiErr smithy.APIError
			if errors.As(headErr, &apiErr) {
				if apiErr.ErrorCode() == "NotFound" || apiErr.ErrorCode() == "NoSuchKey" {
					return apis.NewNotFoundError("object not found", headErr)
				}
			}
			// Network or other errors => also treat as not found to avoid leaking object info
			return apis.NewNotFoundError("object not found", headErr)
		}

		// delete pending_upload record
		if err := app.Dao().DeleteRecord(pending); err != nil {
			return apis.NewApiError(500, "failed to delete pending upload", err)
		}

		uploadsCol, err := app.Dao().FindCollectionByNameOrId("uploads")
		if err != nil {
			return apis.NewApiError(500, "uploads collection missing", err)
		}

		newRec := models.NewRecord(uploadsCol)
		newRec.Set("user", rec.Id)
		newRec.Set("key", key)
		if err := app.Dao().SaveRecord(newRec); err != nil {
			return apis.NewApiError(500, "failed to save upload", err)
		}

		return e.JSON(200, map[string]any{
			"key": key,
		})
	}
}

func main() {
	app := pocketbase.New()

	app.OnServe().Bind(&hook.Handler[*core.ServeEvent]{
		Func: func(e *core.ServeEvent) error {
			if err := ensureCollections(e.App); err != nil {
				return err
			}
			cfg := loadS3Config()
			s3Client, err := newS3Client(context.Background(), cfg)
			if err != nil {
				return err
			}

