	"os"
	"strings"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/credentials"
	"github.com/aws/aws-sdk-go-v2/service/s3"
	"github.com/aws/smithy-go"
	"github.com/google/uuid"
	"github.com/pocketbase/pocketbase"
	"github.com/pocketbase/pocketbase/apis"
	"github.com/pocketbase/pocketbase/core"
	"github.com/pocketbase/pocketbase/models"
	"github.com/pocketbase/pocketbase/models/schema"
	"github.com/pocketbase/pocketbase/tools/routine"
)

const (
	defaultEndpoint  = "http://127.0.0.1:9000"
	defaultRegion    = "us-east-1"
	defaultBucket    = "uploads"
	defaultAccessKey = "minioadmin"
	defaultSecretKey = "minioadmin"
	defaultScheme    = "http"
	presignExpires   = 5 * time.Minute
)

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

type s3Config struct {
	Endpoint  string
	Region    string
	Bucket    string
	AccessKey string
	SecretKey string
	UseSSL    bool
}

func loadS3Config() s3Config {
	scheme := envOr("MINIO_SCHEME", defaultScheme)
	return s3Config{
		Endpoint:  envOr("MINIO_ENDPOINT", defaultEndpoint),
		Region:    envOr("MINIO_REGION", defaultRegion),
		Bucket:    envOr("MINIO_BUCKET", defaultBucket),
		AccessKey: envOr("MINIO_ACCESS_KEY", defaultAccessKey),
		SecretKey: envOr("MINIO_SECRET_KEY", defaultSecretKey),
		UseSSL:    scheme == "https",
	}
}

func newS3Client(ctx context.Context, cfg s3Config) (*s3.Client, error) {
	endpoint := cfg.Endpoint
	if !strings.HasPrefix(endpoint, "http://") && !strings.HasPrefix(endpoint, "https://") {
		if cfg.UseSSL {
			endpoint = "https://" + endpoint
		} else {
			endpoint = "http://" + endpoint
		}
	}

	awsCfg, err := config.LoadDefaultConfig(ctx,
		config.WithRegion(cfg.Region),
		config.WithCredentialsProvider(credentials.NewStaticCredentialsProvider(cfg.AccessKey, cfg.SecretKey, "")),
	)
	if err != nil {
		return nil, err
	}

	return s3.NewFromConfig(awsCfg, func(o *s3.Options) {
		o.BaseEndpoint = aws.String(endpoint)
		o.UsePathStyle = true
	}), nil
}

func ensureCollections(app core.App) error {
	if _, err := app.Dao().FindCollectionByNameOrId("pending_upload"); err != nil {
		if !errors.Is(err, sql.ErrNoRows) {
			// continue to create
		}
		col := models.NewBaseCollection("pending_upload")
		col.Fields.Add(
			&schema.SchemaField{Name: "user", Type: schema.FieldTypeRelation, Options: &schema.RelationOptions{MaxSelect: 1, CollectionId: "_pb_users_auth_", Required: true}},
			&schema.SchemaField{Name: "key", Type: schema.FieldTypeText, Options: &schema.TextOptions{Required: true, Pattern: "^[a-f0-9-]{16,}$"}},
			&schema.SchemaField{Name: "expires_at", Type: schema.FieldTypeDate, Options: &schema.DateOptions{Required: true}},
		)
		col.Indexes = []string{"CREATE UNIQUE INDEX idx_pending_upload_key ON pending_upload (key)"}
		if err := app.Dao().SaveCollection(col); err != nil {
			return fmt.Errorf("create pending_upload: %w", err)
		}
		log.Println("created pending_upload collection")
	}

	if _, err := app.Dao().FindCollectionByNameOrId("uploads"); err != nil {
		col := models.NewBaseCollection("uploads")
		col.Fields.Add(
			&schema.SchemaField{Name: "user", Type: schema.FieldTypeRelation, Options: &schema.RelationOptions{MaxSelect: 1, CollectionId: "_pb_users_auth_", Required: true}},
