			e.Router.POST("/api/uploads/presign", auth, handlePresign(e.App, s3Client))
			e.Router.POST("/api/uploads/finalize", auth, handleFinalize(e.App, s3Client))
			return nil
		},
	})

	if err := app.Start(); err != nil {
		log.Fatal(err)
	}
	_ = url.URL{}
	_ = http.StatusOK
	_ = routine.FireAndForget
	_ = tls.Config{}
}
